<template>
 <section class="operations">
  <div class="queues"><button v-for="item in queues" :key="item.key" :class="{selected:queue===item.key}" @click="selectQueue(item)"><span>{{item.title}}</span><strong>{{overview[item.key]||0}}</strong><small>{{item.hint}}</small></button></div>
  <div class="ledger"><span>内部账务 · 全部记录</span><span>订单快照金额 <b>¥{{money(overview.order_due_fen)}}</b></span><span>已收款 <b>¥{{money(overview.paid_fen)}}</b></span><span>已退 <b>¥{{money(overview.refunded_fen)}}</b></span><span>待退 <b>¥{{money(overview.outstanding_refund_fen)}}</b></span><small>不代表可用余额；手续费、冻结和结算金额请核对渠道账单。</small></div>
  <a-alert v-if="error" :message="error" type="error" show-icon closable @close="error=''"/>
  <div class="filters">
   <a-input-search v-model:value="query" :placeholder="kind==='audit'?'关联订单、支付单或退款单号':'订单号、支付/退款单号、作品或流水号'" allow-clear @search="search"/>
   <template v-if="kind!=='audit'"><a-select v-model:value="channel" :options="channels" @change="search"/><a-select v-model:value="state" :options="states" @change="search"/><a-range-picker :locale="dateLocale" :placeholder="['开始日期','结束日期']" v-model:value="range" value-format="YYYY-MM-DD" @change="search"/></template>
   <a-select v-if="kind==='refunds'" v-model:value="category" :options="categories" @change="search"/>
   <template v-if="kind==='audit'"><a-input v-model:value="actor" placeholder="操作人" @press-enter="search"/><a-select v-model:value="result" :options="[{value:'',label:'全部执行结果'},{value:'success',label:'成功'},{value:'failed',label:'失败'}]" @change="search"/></template>
   <a-button @click="reset">重置</a-button><a-button v-if="kind!=='audit'" :loading="exporting" @click="exportLedger">导出当前筛选</a-button><span class="muted">{{count}} 条 · {{lastUpdated?`更新于 ${lastUpdated}`:'尚未更新'}}</span>
  </div>
  <a-table :data-source="rows" :columns="columns" row-key="id" :loading="loading" :scroll="{x:kind==='audit'?1120:1460}" :pagination="{current:page,pageSize:30,total:count,showSizeChanger:false}" @change="paginate" :locale="{emptyText:error?'加载失败，请刷新重试':'当前筛选没有记录'}">
   <template #bodyCell="{column,record}">
    <template v-if="column.key==='order'"><a v-if="access.orders" @click="openOrder(record.order_id)">{{record.title}}</a><strong v-else>{{record.title}}</strong><div class="record-id"><span :title="record.order_id">{{short(record.order_id)}}</span><a-button type="link" size="small" @click="copy(record.order_id)">复制</a-button></div><small>{{orderLabel(record.order_state)}}</small></template>
    <template v-else-if="column.key==='id'"><span :title="record.id">{{short(record.id)}}</span><a-button type="link" size="small" @click="copy(record.id)">复制</a-button><small v-if="record.provider_id" :title="record.provider_id">渠道 {{short(record.provider_id)}}</small></template>
    <template v-else-if="column.key==='channel'">{{channelName(record.channel)}}</template>
    <template v-else-if="column.key==='amount'"><strong>¥{{money(record.amount)}}</strong></template>
    <template v-else-if="column.key==='state'"><a-tag :color="tone(record.state)">{{labelState(record.state)}}</a-tag><div v-if="record.refund"><a @click="go('refunds',record.refund.id)">退款：{{label(record.refund.state)}} ¥{{money(record.refund.amount)}}</a></div><small v-if="kind==='refunds'">原支付：{{label(record.payment_state)}}</small></template>
    <template v-else-if="column.key==='times'"><div>申请 {{date(record.created_at)}}</div><small v-if="record.paid_at">支付 {{date(record.paid_at)}}</small><small>核对 {{date(record.checked_at)}}</small><small v-if="record.completed_at">退完 {{date(record.completed_at)}}</small></template>
    <template v-else-if="column.key==='recovery'"><div v-if="record.last_error" class="error-text">{{record.last_error}}</div><small v-if="record.error_code">{{record.error_code}}</small><small v-if="record.recovery_action">{{record.recovery_action}}</small><small v-if="kind==='refunds'">{{record.retry_mode==='paused'?'已暂停自动处理':'自动处理'}} · 失败 {{record.failure_count||0}} 次</small><small v-if="record.next_check_at">下次 {{date(record.next_check_at)}}</small><span v-if="!record.last_error&&kind==='transactions'" class="muted">—</span></template>
    <template v-else-if="column.key==='actions'"><div class="actions"><a-button size="small" @click="openDetail(record)">详情</a-button><template v-if="kind==='transactions'"><a-button v-if="access.query" size="small" :loading="working===record.id" @click="operate(record,'query')">查询支付结果</a-button><a-button v-if="access.query&&!['succeeded','closed','failed'].includes(record.state)" size="small" @click="prepare(record,'close')">关闭支付</a-button></template><template v-else-if="kind==='refunds'"><a-button v-if="access.query" size="small" :loading="working===record.id" @click="operate(record,'query')">查询渠道结果</a-button><a-button v-if="access.refund&&record.state!=='success'" size="small" type="primary" @click="prepare(record,'retry')">重试退款</a-button><a-button v-if="access.refund&&record.state!=='success'" size="small" @click="record.retry_mode==='paused'?prepare(record,'resume'):operate(record,'pause')">{{record.retry_mode==='paused'?'恢复自动处理':'暂停自动处理'}}</a-button></template><a-button v-if="kind==='audit'&&record.reference?.includes('-')&&!record.action.startsWith('probe_')" size="small" @click="go(record.action.startsWith('refund_')?'refunds':'transactions',record.reference)">关联记录</a-button></div></template>
    <template v-else-if="column.key==='action'">{{actionLabel(record.action)}}</template>
    <template v-else-if="column.key==='reference'"><span :title="record.reference">{{short(record.reference)}}</span><a-button size="small" type="link" @click="copy(record.reference)">复制</a-button></template>
    <template v-else-if="column.key==='auditResult'"><a-tag :color="record.details?.result==='failed'?'red':record.details?.result==='success'?'green':'default'">{{record.details?.result==='failed'?'失败':record.details?.result==='success'?'成功':'事件记录'}}</a-tag><small>{{record.details?.source==='automatic'?'自动处理':record.details?.source==='manual'?'人工操作':''}}</small><small v-if="record.details?.error_code">{{record.details.error_code}}</small></template>
    <template v-else-if="column.key==='auditTime'">{{date(record.created_at)}}</template>
   </template>
  </a-table>
  <a-drawer :open="!!detail" :title="kind==='refunds'?'退款详情':kind==='audit'?'操作记录详情':'支付详情'" :width="'min(760px, 100vw)'" @close="detail=null"><template #extra><a-button :loading="loading" @click="load">刷新详情</a-button></template><template v-if="detail">
   <a-alert v-if="error" :message="error" type="error" show-icon/>
   <h3>关联订单</h3><p>{{detail.title||'操作记录'}} <a v-if="access.orders&&detail.order_id" @click="openOrder(detail.order_id)">打开印制订单</a></p><a-typography-text copyable>{{detail.order_id||detail.reference}}</a-typography-text>
   <a-descriptions v-if="kind!=='audit'" title="金额与结果" bordered :column="1" class="detail-block"><a-descriptions-item label="记录单号"><a-typography-text copyable>{{detail.id}}</a-typography-text></a-descriptions-item><a-descriptions-item label="渠道">{{channelName(detail.channel)}} · 配置版本 {{detail.config_version||'—'}}</a-descriptions-item><a-descriptions-item label="金额">¥{{money(detail.amount)}}</a-descriptions-item><a-descriptions-item label="状态">{{label(detail.state)}} · {{orderLabel(detail.order_state)}}</a-descriptions-item><a-descriptions-item v-if="detail.provider_id" label="渠道流水号"><a-typography-text copyable>{{detail.provider_id}}</a-typography-text></a-descriptions-item><a-descriptions-item label="创建 / 最近查询">{{date(detail.created_at)}} / {{date(detail.checked_at)}}（北京时间）</a-descriptions-item><a-descriptions-item v-if="detail.completed_at" label="退款完成">{{date(detail.completed_at)}}</a-descriptions-item></a-descriptions>
   <div v-if="detail.refund||kind==='refunds'" class="detail-block"><h3>退款进度</h3><template v-if="detail.refund"><p>{{label(detail.refund.state)}} · ¥{{money(detail.refund.amount)}}</p><a-button @click="go('refunds',detail.refund.id)">查看这笔退款</a-button></template><template v-else><p>{{detail.reason}}</p><p>{{detail.last_error||'暂无异常'}} <code>{{detail.error_code}}</code></p><p>{{detail.recovery_action}}</p><p>{{detail.retry_mode==='paused'?'已暂停自动处理':'自动处理已开启'}} · 失败 {{detail.failure_count||0}} 次 · 下次 {{date(detail.next_check_at)}}</p><a-button @click="go('transactions',detail.attempt_id)">查看原支付</a-button></template></div>
   <a-descriptions v-if="kind==='audit'" title="执行结果" bordered :column="1"><a-descriptions-item label="操作">{{actionLabel(detail.action)}}</a-descriptions-item><a-descriptions-item label="操作人">{{detail.actor}}</a-descriptions-item><a-descriptions-item label="结果">{{detail.details?.result==='failed'?'失败':detail.details?.result==='success'?'成功':'事件记录'}}</a-descriptions-item><a-descriptions-item label="状态变化">{{label(detail.details?.before)}} → {{label(detail.details?.after)}}</a-descriptions-item><a-descriptions-item label="渠道错误码">{{detail.details?.error_code||'—'}}</a-descriptions-item><a-descriptions-item label="时间（北京时间）">{{date(detail.created_at)}}</a-descriptions-item></a-descriptions>
   <h3>处理记录</h3><a-timeline v-if="detailAudit.length"><a-timeline-item v-for="event in detailAudit" :key="event.id"><strong>{{actionLabel(event.action)}}</strong> · {{event.actor}}<p>{{date(event.created_at)}} · {{event.details?.result==='failed'?'失败':event.details?.result==='success'?'成功':'事件'}}</p><small v-if="event.details?.before">{{label(event.details.before)}} → {{label(event.details.after)}}</small><p>{{event.details?.error_code}}</p></a-timeline-item></a-timeline><a-empty v-else description="暂无处理记录"/>
  </template></a-drawer>
  <a-modal :open="!!confirmation" :title="confirmation?.action==='close'?'核对并关闭支付交易':'核对退款操作'" :confirm-loading="!!working" @ok="confirm" @cancel="confirmation=null"><template v-if="confirmation"><a-alert v-if="error" :message="error" type="error" show-icon/><p>作品：{{confirmation.row.title}}</p><p>订单：{{confirmation.row.order_id}}</p><p>记录：{{confirmation.row.id}}</p><p>{{channelName(confirmation.row.channel)}} · ¥{{money(confirmation.row.amount)}}</p><p v-if="confirmation.row.last_error">当前原因：{{confirmation.row.last_error}}</p><p>{{confirmation.action==='close'?'先核对渠道结果，已付款不会关闭。关闭支付交易不等于取消印制订单。':'先查询已有退款，再使用原退款单号提交，确认后可能立即原路退款。'}}</p></template></a-modal>
 </section>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {message} from 'ant-design-vue';
import dateLocale from 'ant-design-vue/es/date-picker/locale/zh_CN';
import http from '../../api/http';
const props=defineProps<{kind:string;access:{view:boolean;query:boolean;refund:boolean;orders:boolean};refreshKey:number}>();
const route=useRoute(),router=useRouter(),base='/api/admin/v1/print/payments/';
type Row=Record<string,any>;
const rows=ref<Row[]>([]),overview=ref<Record<string,number>>({}),query=ref(String(route.query.q||'')),channel=ref(''),state=ref(''),category=ref(''),actor=ref(''),result=ref(''),queue=ref(''),range=ref<string[]>([]),page=ref(1),count=ref(0),loading=ref(false),working=ref(''),exporting=ref(false),error=ref(''),lastUpdated=ref(''),detail=ref<Row|null>(null),detailAudit=ref<Row[]>([]),confirmation=ref<{row:Row;action:string}|null>(null);
let sequence=0,timer:ReturnType<typeof setInterval>|undefined;
const channels=[{value:'',label:'全部渠道'},{value:'alipay',label:'支付宝'},{value:'wechat',label:'微信支付'}];
const labels:Record<string,string>={creating:'准备支付',pending:'等待处理',unknown:'结果待核实',succeeded:'支付成功',closed:'支付已关闭',failed:'支付失败',processing:'渠道退款处理中',blocked:'退款受阻',exception:'需人工处理',success:'退款成功'};
const label=(v:string)=>labels[v]||v||'—';
const orderLabels:Record<string,string>={draft:'待完成提交',awaiting_review:'待审核',queued:'待制作',producing:'制作中',in_production:'制作中',ready_to_ship:'待发货',shipped:'已发货',completed:'已完成',cancelled:'订单已取消',needs_revision:'待修改',paused:'制作暂停'};
const orderLabel=(v:string)=>orderLabels[v]||v||'—';
const labelState=(v:string)=>v==='pending'?(props.kind==='refunds'?'等待提交退款':'等待付款'):label(v);
const states=computed(()=>[{value:'',label:'全部状态'},...(props.kind==='refunds'?[{value:'open',label:'全部待完成退款'},{value:'blocked_all',label:'全部受阻退款'}]:[]),...(props.kind==='refunds'?['pending','processing','blocked','unknown','exception','success']:['creating','pending','unknown','succeeded','closed','failed']).map(value=>({value,label:labelState(value)}))]);
const categories=[{value:'',label:'全部异常原因'},{value:'balance',label:'资金不足'},{value:'permission',label:'权限异常'},{value:'configuration',label:'配置异常'},{value:'business',label:'渠道业务限制'},{value:'unknown',label:'结果未知'}];
const queues=[{key:'uncertain',title:'支付待核实',hint:'查询渠道结果',kind:'transactions',state:''},{key:'processing',title:'待完成退款',hint:'待提交、处理中或待核实',kind:'refunds',state:'open'},{key:'blocked',title:'退款受阻',hint:'补足资金或处理异常',kind:'refunds',state:'blocked_all'},{key:'paused',title:'自动处理已暂停',hint:'需要人工接管',kind:'refunds',state:''}];
const columns=computed(()=>props.kind==='audit'?[{title:'操作人',dataIndex:'actor',width:110},{title:'操作',key:'action',width:180},{title:'关联记录',key:'reference',width:210},{title:'执行结果',key:'auditResult',width:230},{title:'时间（北京时间）',key:'auditTime',width:180},{title:'操作',key:'actions',width:160,fixed:'right' as const}]:[{title:'作品 / 订单号',key:'order',width:200},{title:props.kind==='refunds'?'退款单号':'支付单号',key:'id',width:190},{title:'渠道',key:'channel',width:90},{title:'金额',key:'amount',width:100},{title:'支付 / 退款状态',key:'state',width:200},{title:'时间（北京时间）',key:'times',width:210},{title:'异常与恢复',key:'recovery',width:270},{title:'操作',key:'actions',width:200,fixed:'right' as const}]);
const money=(v:number=0)=>(v/100).toFixed(2),short=(v:string='')=>v.length>20?v.slice(0,8)+'…'+v.slice(-6):v;
const date=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const channelName=(v:string)=>v==='alipay'?'支付宝':v==='wechat'?'微信支付':v||'—';
const tone=(v:string)=>['success','succeeded'].includes(v)?'green':['blocked','exception','unknown'].includes(v)?'red':['pending','processing'].includes(v)?'orange':'default';
const actionNames:Record<string,string>={query:'查询渠道结果',retry:'重试退款',resume:'恢复自动处理',pause:'暂停自动处理',auto:'自动核对退款',sync:'历史退款核对',blocked:'退款受阻',unknown:'退款结果待核实',exception:'退款需人工处理',success:'退款成功',processing:'退款处理中',config_save:'保存配置',config_check:'检查配置',config_publish:'启用渠道',config_disable:'停用渠道',config_position:'调整渠道顺序',paid:'确认付款',duplicate_payment:'重复支付补偿',ledger_export:'导出账务'};
function actionLabel(v:string){if(actionNames[v])return actionNames[v];if(v.startsWith('refund_'))return actionNames[v.slice(7)]||v;if(v.startsWith('transaction_'))return v.endsWith('close')?'关闭支付交易':'查询支付结果';if(v.startsWith('probe_'))return '联调 · '+({create:'创建',query:'查询',close:'结束'}[v.slice(6)]||v);return v}
const params=()=>({q:query.value,channel:channel.value,state:state.value,queue:queue.value,error_category:category.value,actor:actor.value,result:result.value,date_from:range.value?.[0],date_to:range.value?.[1],page:page.value});
async function load(){const seq=++sequence;loading.value=true;try{const [list,stats]=await Promise.all([http.get(base+props.kind+'/',{params:params()}),http.get(base+'overview/')]) as unknown as [{results:Row[];count:number},Record<string,number>];if(seq!==sequence)return;rows.value=list.results;count.value=list.count;overview.value=stats;lastUpdated.value=new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});if(detail.value){const id=detail.value.id;const fresh=list.results.find(r=>r.id===id);if(fresh)detail.value=fresh;else{const res=await http.get(base+props.kind+'/',{params:{id}}) as unknown as {results:Row[]};if(seq===sequence&&detail.value?.id===id&&res.results[0])detail.value=res.results[0]}}}catch(e){if(seq===sequence)error.value=explain(e)}finally{if(seq===sequence)loading.value=false}}
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败';
function search(){page.value=1;error.value='';void load()}
function reset(){query.value='';channel.value='';state.value='';category.value='';actor.value='';result.value='';queue.value='';range.value=[];search()}
function paginate(p:{current?:number}){page.value=p.current||1;void load()}
function go(section:string,q:string){detail.value=null;confirmation.value=null;void router.push({path:'/print-payments',query:{section,q}})}
function selectQueue(item:typeof queues[number]){if(props.kind!==item.kind){void router.push({path:'/print-payments',query:{section:item.kind,queue:item.key}});return}reset();queue.value=item.key;state.value=item.state;search()}
function openOrder(id:string){void router.push({path:'/print-orders',query:{order:id}})}
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.success('已复制')}catch{message.error('复制失败')}}
async function openDetail(row:Row){detail.value=row;detailAudit.value=[];try{const data=await http.get(base+'audit/',{params:{q:props.kind==='audit'?row.reference:row.id}}) as unknown as {results:Row[]};if(detail.value?.id===row.id)detailAudit.value=data.results}catch(e){error.value=explain(e)}}
function prepare(row:Row,action:string){error.value='';confirmation.value={row,action}}
async function operate(row:Row,action:string,confirmed=false){if(working.value)return false;working.value=row.id;error.value='';let success=false;try{const updated=await http.post(base+props.kind+'/',{id:row.id,action,confirmed}) as unknown as Row;message.success(action==='query'?`已同步：${label(updated.state)}`:'操作完成');success=true}catch(e){error.value=explain(e)}finally{await load();if(detail.value&&detail.value.id===row.id)await openDetail(detail.value);working.value=''}return success}
async function confirm(){const c=confirmation.value;if(c&&await operate(c.row,c.action,true))confirmation.value=null}
async function exportLedger(){exporting.value=true;try{const data=await http.get(base+'export/',{params:{...params(),kind:props.kind}}) as unknown as {filename:string;csv:string};const url=URL.createObjectURL(new Blob([data.csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=data.filename;a.click();URL.revokeObjectURL(url);message.success('已导出内部账务记录')}catch(e){error.value=explain(e)}finally{exporting.value=false}}
function applyRoute(){query.value=String(route.query.q||'');queue.value=String(route.query.queue||'');if(queue.value==='processing')state.value='open';if(queue.value==='blocked')state.value='blocked_all';page.value=1;void load()}
watch(()=>[props.kind,route.query.q,route.query.queue],applyRoute);watch(()=>props.refreshKey,()=>{error.value='';void load()});
onMounted(()=>{applyRoute();timer=setInterval(()=>{if(!working.value&&!confirmation.value&&document.visibilityState==='visible')void load()},30000)});onBeforeUnmount(()=>{sequence++;if(timer)clearInterval(timer)});
</script>
<style scoped>
.operations{display:flex;flex-direction:column;gap:18px;min-width:0}.queues{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.queues button{border:1px solid #dce5ef;background:white;border-radius:12px;text-align:left;padding:16px;cursor:pointer;display:flex;flex-direction:column;gap:7px}.queues button.selected{border-color:#1677ff;background:#f0f7ff}.queues strong{font-size:28px;line-height:1.2}.ledger{display:flex;flex-wrap:wrap;gap:12px 24px;padding:14px 18px;background:#f6f8fb;border-radius:10px}.ledger small{width:100%}.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.filters>.ant-input-search{width:330px;max-width:100%}.filters>.ant-input{width:160px}.filters>.ant-select{min-width:145px}.muted,small{color:#748095;font-size:12px}small{display:block;line-height:1.65}.record-id{display:flex;align-items:center;gap:2px;font-size:12px;color:#64748b}.actions{display:flex;flex-wrap:wrap;gap:8px}.error-text{color:#b42318}.detail-block{margin:24px 0}.operations :deep(.ant-table-cell){vertical-align:top;word-break:normal}.operations :deep(.ant-tag){white-space:nowrap}.operations :deep(.ant-table-body){overflow-x:auto}code{overflow-wrap:anywhere}h3{margin:22px 0 12px}@media(max-width:900px){.queues{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
